import{_ as t,o,c as i,a2 as d}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"Terminal viewer (/cli)","description":"","frontmatter":{},"headers":[],"relativePath":"api/terminal.md","filePath":"api/terminal.md"}'),a={name:"api/terminal.md"};function c(n,e,r,s,l,h){return o(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="terminal-viewer-cli" tabindex="-1">Terminal viewer (<code>/cli</code>) <a class="header-anchor" href="#terminal-viewer-cli" aria-label="Permalink to &quot;Terminal viewer (`/cli`) {#terminal-viewer-cli}&quot;">​</a></h1><p>The <code>/cli</code> chat command opens a live, <strong>agent-scoped</strong> webview terminal for an agent running with <code>gateway.headless: false</code>. Unlike <code>/dashboard</code> (admin, host-wide), a <code>/cli</code> session can only ever reach the single agent that the pairing was created for — it never issues or accepts the admin <code>dash_session</code> cookie. Requires <code>gateway.publicUrl</code> to be set (the absolute, externally-reachable origin used to build the link); when unset, <code>/cli</code> replies that the viewer is not configured.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/cli/:pairingId</code></td><td>Pairing (binds the browser)</td><td>Device page — &quot;waiting for approval&quot; (Discord/LINE) or Telegram Mini App initData submit</td></tr><tr><td><code>GET</code></td><td><code>/cli/:pairingId/status</code></td><td><code>cli_pair</code> cookie</td><td>Poll; issues the agent-scoped <code>cli_session</code> cookie once approved</td></tr><tr><td><code>POST</code></td><td><code>/cli/:pairingId/tg-init</code></td><td>Telegram initData</td><td>Verify the signed initData (HMAC with the agent&#39;s bot token) and unlock</td></tr><tr><td><code>GET</code></td><td><code>/cli/:pairingId/view</code></td><td><code>cli_session</code> cookie</td><td>The xterm.js viewer, scoped to the pairing&#39;s agent (read-only by default)</td></tr><tr><td><code>GET</code></td><td><code>/cli/:pairingId/sessions</code></td><td><code>cli_session</code> cookie</td><td>The agent&#39;s live <code>pty-shell</code> sessions to attach to</td></tr><tr><td><code>POST</code></td><td><code>/cli/:pairingId/pty-ticket</code></td><td><code>cli_session</code> cookie</td><td>One-time PTY ticket, validated to belong to the pairing&#39;s agent</td></tr></tbody></table><p><strong>Authorization model.</strong> The link is not a credential. Unlocking requires proof bound to an allowlist-gated chat action: <strong>Telegram</strong> submits a signed Mini App <code>initData</code> (verified against the agent&#39;s bot token; the <code>initData</code> user must match the pairing&#39;s user), while <strong>Discord</strong> and <strong>LINE</strong> require the operator to tap <strong>Approve</strong> in the chat. The first browser to open a link owns it (a link opened in a second browser is rejected), and the <code>cli_pair</code> / <code>cli_session</code> cookies are <code>HttpOnly</code> and scoped to the pairing&#39;s path only.</p>',4)])])}const m=t(a,[["render",c]]);export{g as __pageData,m as default};
